package com.hookdeveloper.catlive.remote;
import android.app.Dialog;import android.graphics.Typeface;import android.os.SystemClock;import android.view.*;import android.widget.*;import java.nio.charset.StandardCharsets;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31,qualifiers="w393dp-h851dp-port")
public class RemoteTimerPanelTest {
 ActivityController<MainActivity> controller;MainActivity app;RemoteTimerPanel panel;
 @Before public void start()throws Exception{controller=Robolectric.buildActivity(MainActivity.class).setup();app=controller.get();app.entering=true;app.remote.connected=true;app.remote.mode="director";app.remote.state=new JSONObject(new String(getClass().getResourceAsStream("/remote-state.json").readAllBytes(),StandardCharsets.UTF_8));app.onChanged();app.timer();panel=app.activeDialog.findViewById(android.R.id.content).findViewWithTag("timer-panel");}
 @After public void close(){app.closeDialog();controller.pause().stop().destroy();}
 @Test public void phoneUsesCompactBottomSheetWithThreeRememberedComponents(){assertNotNull(panel);assertEquals(Gravity.BOTTOM,app.activeDialog.getWindow().getAttributes().gravity);assertEquals(-1,app.activeDialog.getWindow().getAttributes().width);assertEquals("00",panel.fields[0].getText().toString());assertEquals("05",panel.fields[1].getText().toString());assertEquals("00",panel.fields[2].getText().toString());assertEquals("00:05:00",panel.readout.getText().toString());assertEquals(RemoteWidgets.dp(40),panel.fields[0].getLayoutParams().height);assertEquals(26,panel.readout.getTextSize()/app.getResources().getDisplayMetrics().scaledDensity,0.01);}
 @Test public void startingDoesNotClosePanelAndUpdatesBeforeDesktop(){panel.fields[0].setText("01");panel.fields[1].setText("02");panel.fields[2].setText("03");Dialog dialog=app.activeDialog;panel.toggle.performClick();assertTrue(dialog.isShowing());assertTrue(app.localTimer.running);assertEquals(3723,app.localTimer.targetSeconds);assertFalse(panel.fields[0].isEnabled());assertEquals(RemoteText.ui("Stop"),panel.toggle.getText().toString());assertEquals("01:02:03",panel.readout.getText().toString());}
 @Test public void digitsClampLikeIOSAndEditingSurvivesUnrelatedRefresh(){panel.fields[1].setText("99");panel.fields[2].setText("99");panel.refresh();assertEquals("99",panel.fields[1].getText().toString());panel.toggle.performClick();assertEquals(3599,app.localTimer.targetSeconds);assertEquals("59",panel.fields[1].getText().toString());assertEquals("59",panel.fields[2].getText().toString());assertEquals(359999,RemoteTimerPanel.targetSeconds("99","99","99"));assertEquals(0,RemoteTimerPanel.targetSeconds("","",""));}
 @Test public void stopRequiresConfirmationCancelKeepsRunningAndConfirmRetainsDuration(){panel.toggle.performClick();long run=app.localTimer.runID;panel.toggle.performClick();assertTrue(app.localTimer.running);assertNotNull(panel.confirmation);panel.confirmation.dismiss();assertTrue(app.localTimer.running);assertEquals(run,app.localTimer.runID);panel.toggle.performClick();panel.confirmation.findViewById(android.R.id.content).findViewWithTag("timer-confirm-stop").performClick();assertFalse(app.localTimer.running);assertEquals(300,app.localTimer.targetSeconds);assertEquals("00:00:00",panel.readout.getText().toString());assertEquals("05",panel.fields[1].getText().toString());assertTrue(panel.dialog.isShowing());}
 @Test public void staleStopCannotStopNewRunAndClosingDoesNotStopTimer()throws Exception{panel.toggle.performClick();panel.toggle.performClick();Dialog confirmation=panel.confirmation;View stop=confirmation.findViewById(android.R.id.content).findViewWithTag("timer-confirm-stop");app.localTimer.command(new JSONObject().put("id","other-start").put("action","timerStart").put("value",90),SystemClock.elapsedRealtime());stop.performClick();assertTrue(app.localTimer.running);assertEquals(90,app.localTimer.targetSeconds);panel.dialog.dismiss();assertTrue(app.localTimer.running);app.timer();RemoteTimerPanel reopened=app.activeDialog.findViewById(android.R.id.content).findViewWithTag("timer-panel");assertEquals("01",reopened.fields[1].getText().toString());assertEquals("30",reopened.fields[2].getText().toString());}
 @Test @Config(qualifiers="w1024dp-h768dp-land") public void tabletUsesBoundedPopoverWidth(){assertTrue(RemoteWidgets.tablet);assertEquals(RemoteWidgets.dp(300),app.activeDialog.getWindow().getAttributes().width);assertTrue(panel.dialog.isShowing());}
}
